import{_ as t,H as a,f as n,i}from"./chunks/framework.BH2BK_3i.js";const P=JSON.parse('{"title":"结束语 | 与eBPF共赴技术革新之约","description":"","frontmatter":{},"headers":[],"relativePath":"eBPF核心技术与实战/结束语｜与eBPF共赴技术革新之约.md","filePath":"eBPF核心技术与实战/结束语｜与eBPF共赴技术革新之约.md","lastUpdated":1795536221000}'),s={name:"eBPF核心技术与实战/结束语｜与eBPF共赴技术革新之约.md"};function p(_,e,B,r,o,F){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="结束语-与ebpf共赴技术革新之约" tabindex="-1">结束语 | 与eBPF共赴技术革新之约 <a class="header-anchor" href="#结束语-与ebpf共赴技术革新之约" aria-label="Permalink to &quot;结束语 | 与eBPF共赴技术革新之约&quot;">​</a></h1><p>你好，我是倪朋飞。</p><p>不知不觉，四年时光已经过去，咱们专栏也到了该说再见的时候。诸多感慨和收获，在这里想跟你一起分享一下。</p><p>回想当初，在确认专栏写作形式的时候，以案例实践贯穿 eBPF 原理成为整个专栏的主线。同时，考虑到 eBPF 是 Linux 内核社区最活跃的模块之一，我在开篇词中承诺了一个“四年技术雷达之约“，每季度更新一篇，持续跟踪内核和开源社区的最新进展。今天，我很高兴地告诉你：这个承诺，我们一起兑现了。</p><p>说实话，四年前立下这个约定时，我心里也有些忐忑。eBPF 的发展速度太快了，Linux 内核每三个月一个版本，每个版本都有大量新特性。要保证每季度的内容既紧跟前沿又有实用价值，压力不小。最大的挑战是平衡“新”和“用”：有些内核特性非常前沿，但可能要等一两年才进入主流发行版；有些生态工具很热门，但实际生产环境的最佳实践还在摸索中。</p><p>专栏上线后，大家热情的留言完全出乎我的意料。这些留言既有关于技术细节的深入讨论，也有实际生产环境的分享。让我印象最深的是有位运维同学留言说，他用第 10 讲的网络跟踪方法，终于追到了困扰团队半年的 conntrack 表溢出问题，发现是一个旧版微服务在疯狂创建短连接。这种“原来如此”的时刻，我相信你也体验过。每当看到这样的反馈，我都会异常兴奋，能够把学到的知识应用到实际工作中，这才是技术学习的最大价值。</p><p>这四年，我们一起见证了 eBPF 从实验性技术逐步走向基础设施平台：CO-RE 与 BTF 在主流发行版与生态中已成常态；Cilium 迎来十周年；sched_ext(SCX) 开始在部分大型集群场景落地；同时，自 Linux 6.18 起，内核提供了 BPF 程序签名的初始支持，供应链安全与可控性迈出关键一步。另一方面，在大模型浪潮下，eBPF 也和 AI 形成了有趣的互动：一端是 eBPF为大模型训练和推理系统带来零侵入的可观测性，另一端是利用 Claude Code 这样的 AI 编程工具可以用自然语言辅助生成 eBPF 追踪程序。</p><p>还记得《Linux 性能优化实战》专栏吗？那门课帮助很多同学掌握了 Linux 性能分析的基础技能。而这门 eBPF 课程，可以说是性能优化的进阶篇。如果说性能优化教你看懂系统，那么eBPF 教你掌控系统。这两门课程一脉相承，共同构建了从观察到掌控的完整技能体系。</p><p>最后，非常感谢你的订阅和陪伴。四年前，我邀请你”共赴一场技术革新之约“。今天，这个约定圆满完成。专栏结束了，但我们的交流还将在留言区继续。当然，我也非常希望可以听听你在学习这个专栏时都有哪些感想，也欢迎你在留言区写下你的收获。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/eBPF%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/eBPF%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" alt=""></a></p>',10)])])}const c=t(s,[["render",p]]);export{P as __pageData,c as default};
